    for (int y = 0; y < height(); ++y) {
        for (int x = 0; x < width(); ++x) {
            if (x == playerX && y == playerY) {
                std::cout << '@';   // drawn on top, never stored
            } else {
                std::cout << rows_[y][x];
            }
        }
        std::cout << "\n";
    }
}

